function report(rows){
  const out = new Map();
  for (const r of rows){
    if (r.total > 100) {
      const cur = out.get(r.c) || { c: r.c, sum: 0 };
      cur.sum += r.total;
      out.set(r.c, cur);
    }
  }
  return [...out.values()];
}

tasks.verify:
const rows=[{c:1,total:60},{c:1,total:60},{c:2,total:200}];
const res=report(rows).sort((a,b)=>a.c-b.c);
